"""Dependency-free operational dashboard served by the Sandfleet controller."""

DASHBOARD_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Sandfleet</title><style>
:root{color-scheme:dark;--bg:#0b1020;--card:#151c30;--line:#27324c;--text:#eef3ff;--muted:#9eabc7;--good:#62d6a6;--bad:#ff7b86;--accent:#72a8ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 ui-monospace,SFMono-Regular,Menlo,monospace}main{max-width:1300px;margin:auto;padding:28px}header{display:flex;gap:16px;align-items:center;justify-content:space-between;flex-wrap:wrap}h1{font-size:25px;margin:0}.muted{color:var(--muted)}input,button{background:#10172a;border:1px solid var(--line);color:var(--text);padding:9px 11px;border-radius:7px}button{cursor:pointer}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin:20px 0}.card,.panel{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:15px}.value{font-size:25px;margin-top:5px}.good{color:var(--good)}.bad{color:var(--bad)}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px 8px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-weight:500}.panel{overflow:auto;margin-top:12px}#error{color:var(--bad);min-height:20px}@media(max-width:600px){main{padding:16px}}
</style></head><body><main><header><div><h1>Sandfleet</h1><div class="muted">Slurm sandbox fleet control plane</div></div><form id="auth"><input id="token" type="password" autocomplete="off" placeholder="metrics token"><button>Connect</button></form></header><div id="error"></div><section class="grid" id="cards"></section><section class="panel"><table><thead><tr><th>Pool</th><th>Resources</th><th>Ready</th><th>Free</th><th>Leases</th><th>Queued</th><th>Workers</th><th>Health</th></tr></thead><tbody id="pools"></tbody></table></section><section class="panel"><table><thead><tr><th>Agent</th><th>Node</th><th>Pool</th><th>Prepared</th><th>Free</th><th>Preparing</th><th>Status</th><th>Heartbeat</th></tr></thead><tbody id="agents"></tbody></table></section><div class="muted" id="updated"></div></main><script>
const token=document.querySelector('#token'), err=document.querySelector('#error'); token.value=sessionStorage.sandfleetToken||'';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function card(k,v){return `<div class="card"><div class="muted">${esc(k)}</div><div class="value">${esc(v)}</div></div>`}
async function refresh(){if(!token.value)return;try{const r=await fetch('/v1/metrics',{headers:{Authorization:`Bearer ${token.value}`}});if(!r.ok)throw Error(`${r.status} ${r.statusText}`);const d=await r.json();err.textContent='';document.querySelector('#cards').innerHTML=[card('Scheduler',d.scheduler.ok?'healthy':'error'),card('Prepared',d.totals.ready_capacity),card('Free',d.totals.free_capacity),card('Active leases',d.totals.active_leases),card('Queued',d.totals.pending_leases),card('Step permits',`${d.step_limiter.rate_per_second}/s`) ].join('');document.querySelector('#pools').innerHTML=d.pools.map(p=>`<tr><td>${esc(p.name)}${p.dynamic?' · dynamic':''}</td><td>${p.cpus} CPU / ${p.memory_mb} MiB</td><td>${p.ready_capacity}/${p.target_capacity}</td><td>${p.free_capacity}</td><td>${p.active_leases}</td><td>${p.pending_leases}</td><td>${p.current_workers}</td><td class="${p.scaling_suspended?'bad':'good'}">${p.scaling_suspended?'suspended':'ok'}</td></tr>`).join('');document.querySelector('#agents').innerHTML=d.agents.map(a=>`<tr><td>${esc(a.agent_id)}</td><td>${esc(a.node)}</td><td>${esc(a.pool)}</td><td>${a.ready_slots}/${a.slots}</td><td>${a.free_slots}</td><td>${a.preparing_slots}</td><td>${esc(a.status)}</td><td>${Math.round(Date.now()/1000-a.last_heartbeat)}s</td></tr>`).join('');document.querySelector('#updated').textContent=`Updated ${new Date().toLocaleTimeString()} · uptime ${Math.round(d.uptime_seconds)}s`;}catch(e){err.textContent=`Metrics unavailable: ${e.message}`}}
document.querySelector('#auth').onsubmit=e=>{e.preventDefault();sessionStorage.sandfleetToken=token.value;refresh()};refresh();setInterval(refresh,5000);
</script></body></html>"""
